// lib/placeholderProductPhoto.js
// Temporary stand-in photo for products that don't have a real one yet — used by
// components/admin/ProductsPage.jsx's "Add Placeholder Photo" bulk action (Admin → Products).
// This is a HESEOS smart-home lifestyle shot supplied by the team, downsized/compressed the
// same way ProductsPage.jsx's own client-side upload does (canvas.toDataURL('image/jpeg', ...)),
// so it's stored on a product's `photos` array in exactly the same shape a real upload would be
// — nothing else in the app (CatalogueScreen, QuotationBuilder, quotationPdf.jsx) needs to treat
// it specially. Once a product gets its own real photo, a normal photo upload/edit simply
// replaces this one — there's no cleanup step required here.
export const PLACEHOLDER_PRODUCT_PHOTO = {
  id: 'placeholder-heseos-default',
  name: 'placeholder.jpg',
  dataUrl: 'data:image/jpeg;base64,',
};
